(function(){"use strict";self.onmessage=async t=>{const{file:a,token:r,aiServiceUrl:o}=t.data;try{const e=new FormData;e.append("file",a);const s=await fetch(`${o}/api/receipts/parse`,{method:"POST",headers:{Authorization:`Bearer ${r}`},body:e});if(!s.ok)throw new Error(`API returned status ${s.status}`);const c=await s.json();self.postMessage({success:!0,data:c})}catch(e){self.postMessage({success:!1,error:e.message})}}})();
